#ifndef FE2_PANELS_PANEL_TABLES_H
#define FE2_PANELS_PANEL_TABLES_H

/* Native panels tables (generated by tools/panels_tables_c.py). */
#include <stdint.h>

/* Palette indices copied to the resident colour list; panel drawing uses
 * entries 1 (marker default), 2, 3 (text) and 4. */
extern uint8_t fe2_panels_palette_indices[11];
/* Marker colour by model colour value / 16 (values below 288). */
extern uint8_t fe2_panels_marker_colours[18];
/* Fuel gauge scale by drive class 0..14. */
extern const uint16_t *fe2_panels_drive_gauge_scales;
/* Events the panel overlay accepts. */
extern uint32_t fe2_panels_event_mask;

#endif
